import React from 'react';
import SourcingOfferCard from '../components/';

const offers = [
  {
    id: 1,
    type: 'Buy Offer',
    crop: 'Mango',
    quantity: '10 tonnes',
    location: 'Machakos',
    contact: '+254712345678'
  },
  {
    id: 2,
    type: 'Sell Offer',
    crop: 'Avocado',
    quantity: '4 tonnes',
    location: 'Makueni',
    contact: '+254798112233'
  }
];

const SourcingHubPage = () => (
  <div className="container mx-auto px-4 py-8">
    <h1 className="text-3xl font-bold mb-6 text-center">Sourcing Hub</h1>
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
      {offers.map(offer => (
        <SourcingOfferCard key={offer.id} {...offer} />
      ))}
    </div>
  </div>
);

export default SourcingHubPage;
